package net.civeira.phylax.feature.template.snippetversion.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.snippetversion.domain.SnippetVersion;
import net.civeira.phylax.feature.template.snippetversion.domain.valueobject.SubjectVO;

class SubjectValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of subject of snippet version")
  void test_subject_value_holder_assign_plain_value() {
    Object holder = new Object();
    SubjectValueHolder<Object> value = new SubjectValueHolder<>(holder);
    Assertions.assertSame(holder, value.subject("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getSubjectValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getSubject().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.subjectNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSubjectValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSubject().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of subject of snippet version")
  void test_subject_value_holder_assign_value_object() {
    Object holder = new Object();
    SubjectValueHolder<Object> value = new SubjectValueHolder<>(holder);
    SubjectVO vo = SubjectVO.from("one");
    Assertions.assertFalse(value.getSubjectValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.subject(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSubjectValue().orElseThrow());
    Assertions.assertSame(holder, value.subject(Optional.empty()));
    Assertions.assertFalse(value.getSubjectValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.subject(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSubjectValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of subject of snippet version against the original")
  void test_subject_value_holder_read() {
    Object holder = new Object();
    SubjectValueHolder<Object> value = new SubjectValueHolder<>(holder);
    SubjectVO vo = SubjectVO.from("one");
    SubjectVO other = SubjectVO.from("one");
    SnippetVersion original = Mockito.mock(SnippetVersion.class);
    Mockito.when(original.getSubjectValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSubject(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSubject(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.subject(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSubject(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSubject(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of subject of snippet version")
  void test_subject_value_holder_unset() {
    Object holder = new Object();
    SubjectValueHolder<Object> value = new SubjectValueHolder<>(holder);
    SubjectVO vo = SubjectVO.from("one");
    value.subject(vo);
    Assertions.assertSame(holder, value.unsetSubjectIfMatches("subject_other"));
    Assertions.assertTrue(value.getSubjectValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSubjectIfMatches("subject"));
    Assertions.assertFalse(value.getSubjectValue().isPresent(),
        "The field name must clear the value");
    value.subject(vo);
    Assertions.assertSame(holder, value.unsetSubject());
    Assertions.assertFalse(value.getSubjectValue().isPresent(), "Unset must clear the value");
  }
}
